class Solution:
    def maxAliveYear(self, birth: List[int], death: List[int]) -> int:
        delta = [0] * 102
        for b, d in zip(birth, death):
            delta[b - 1900] += 1
            delta[d - 1900 + 1] -= 1
        best = cur = 0
        best_year = 1900
        for i in range(101):
            cur += delta[i]
            if cur > best:
                best = cur
                best_year = 1900 + i
        return best_year

impl Solution {
  pub fn max_alive_year(birth: Vec<i32>, death: Vec<i32>) -> i32 {
    let mut delta = vec![0i32; 102];
    for i in 0..birth.len() {
      delta[(birth[i] - 1900) as usize] += 1;
      delta[(death[i] - 1900 + 1) as usize] -= 1;
    }
    let (mut best, mut cur, mut best_year) = (0, 0, 1900);
    for i in 0..=100 {
      cur += delta[i];
      if cur > best {
        best = cur;
        best_year = 1900 + i as i32;
      }
    }
    best_year
  }
}

